import sys
import math
from collections import deque

def main():
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        N = int(input[ptr])
        ptr += 1
        adj = [[] for _ in range(N+1)]
        for __ in range(N-1):
            a, b = map(int, input[ptr:ptr+2])
            ptr += 2
            adj[a].append(b)
            adj[b].append(a)
        A = list(map(int, input[ptr:ptr+N]))
        ptr += N

        max_damage = 0
        for v in range(1, N+1):
            visited = [False] * (N+1)
            components = []
            q = deque()
            for u in range(1, N+1):
                if u == v or visited[u]:
                    continue
                q.append(u)
                visited[u] = True
                component = []
                while q:
                    node = q.popleft()
                    component.append(node)
                    for neighbor in adj[node]:
                        if not visited[neighbor] and neighbor != v:
                            visited[neighbor] = True
                            q.append(neighbor)
                if component:
                    components.append(component)
            current_damage = 0
            for comp in components:
                gcd_val = 0
                for node in comp:
                    if gcd_val == 0:
                        gcd_val = A[node-1]
                    else:
                        gcd_val = math.gcd(gcd_val, A[node-1])
                current_damage += gcd_val
            if current_damage > max_damage:
                max_damage = current_damage
        print(max_damage)

if __name__ == '__main__':
    main()
